// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;
    function setUp() public { c = new LRTDepositPool(); }

    function testFuzz_property(uint256 seed, address actor) public {
        vm.assume(actor != address(0));
        // fresh deployment: no pause/unpause has ever been invoked
        // general rule: a freshly deployed LRTDepositPool is NOT paused,
        // so c.paused() must return false, regardless of any caller/input
        vm.prank(actor);
        bool reported;
        try c.paused() returns (bool p) {
            reported = p;
        } catch {
            reported = true; // reverting also breaks the rule of a readable paused flag
        }
        assertTrue(!reported, "fresh contract must not report itself as paused");
    }
}
